function handler(event) {
  var request = event.request;
  var uri = request.uri;
  var isSafeMethod = request.method === 'GET' || request.method === 'HEAD';
  var isSpaRoute = uri === '/' || uri === '/auth/callback' || uri === '/jobs' || uri.indexOf('/jobs/') === 0 || uri.indexOf('/uploads/') === 0;
  if (isSafeMethod && isSpaRoute) {
    request.uri = '/index.html';
  }
  return request;
}

function handler(event) {
  var request = event.request;
  var method = request.method;
  if (method !== 'GET' && method !== 'HEAD' && method !== 'OPTIONS' && method !== 'POST' && method !== 'PUT') {
    return {
      statusCode: 405,
      statusDescription: 'Method Not Allowed',
      headers: {
        'allow': {value: 'GET, HEAD, OPTIONS, POST, PUT'},
        'cache-control': {value: 'private, no-store, max-age=0'},
        'content-security-policy': {value: "default-src 'none'; frame-ancestors 'none'"},
        'content-type': {value: 'application/json'},
        'permissions-policy': {value: 'camera=(), geolocation=(), microphone=(), payment=(), usb=()'},
        'referrer-policy': {value: 'no-referrer'},
        'strict-transport-security': {value: 'max-age=63072000; includeSubDomains; preload'},
        'x-content-type-options': {value: 'nosniff'},
        'x-frame-options': {value: 'DENY'}
      },
      body: {
        encoding: 'text',
        data: '{"error":{"code":"METHOD_NOT_ALLOWED","message":"Method not allowed."}}'
      }
    };
  }
  return request;
}
